{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회의 병목을 분석한 사실에 맞춰 개선 방법을 선택하고 효과를 수치로 확인하는 역량을 검증한다. 신고 목록 조회에 적용한 개선 방법이 병목에 적합하다고 판단한 근거 하나를 묻는다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회가 3.2초 걸렸던 상황이다.",
          "task": "조회 지연을 일으키는 병목에 적합한 쿼리 개선 방법을 판단해야 했다.",
          "action": "실행 계획에서 확인한 조회 구조와 실제 조회 조건을 바탕으로 선택한 개선 방법이 병목을 줄이는 이유를 설명한다.",
          "result": "조회 시간이 3.2초에서 0.4초로 줄어든 측정 결과를 개선 방법의 적합성을 뒷받침하는 근거로 설명한다."
        },
        "expectedEvidence": [
          "선택한 쿼리 개선 방법이 확인된 병목에 적합하다고 판단한 근거",
          "실행 계획의 전체 조인 등 실제 확인한 조회 구조와 개선 방법 사이의 인과관계",
          "개선 전후 조회 시간의 수치 비교로 확인한 효과"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄였을 때, 해당 쿼리 개선 방법이 병목에 적합하다고 판단한 근거는 무엇이었나요?",
      "answerTip": "기억나는 구체적인 사실을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "쿼리 개선 방법이 확인된 병목에 적합하다고 판단한 근거를 구체적으로 설명한다.",
            "실행 계획에서 확인한 조회 구조를 개선 방법이 줄이는 작업과 인과적으로 연결한다.",
            "개선 전후 조회 시간을 수치로 비교해 선택한 방법의 효과를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개선 방법을 선택한 근거는 제시하지만 병목과의 연결이 부분적으로만 드러난다.",
            "실행 계획에서 확인한 사실이나 개선 전후 수치는 언급하지만, 그 사실이 방법의 적합성을 뒷받침하는 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "개선 방법이 병목에 적합하다고 판단한 근거를 제시하지 못한다.",
            "인덱스 추가 등 수행한 작업이나 최종 응답 시간만 나열하고, 원인 분석과 개선 효과의 연결을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류를 로그로 추적한 사실에 근거해 원인에 맞는 복구 방안을 선택하는 역량을 검증한다. 알림 중복 발송 오류에 잠금 키 방식을 적용하기로 판단한 근거 하나를 묻는다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어온 상황이다.",
          "task": "알림 중복 발송의 원인에 맞는 수정 방안을 판단해야 했다.",
          "action": "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행을 근거로, 잠금 키 방식이 해당 오류에 적합한 이유를 설명한다.",
          "result": "잠금 키 방식이 현재의 중복 실행을 막는 효과와 같은 원인으로 다시 발생할 가능성을 줄이는 원리를 구분해 설명한다. 실제 효과는 본인이 확인한 범위에서만 제시한다."
        },
        "expectedEvidence": [
          "잠금 키 방식으로 알림 중복 발송 오류를 고치기로 판단한 근거",
          "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행과 중복 발송 사이의 연결",
          "잠금 키가 동시 실행을 제한해 현재 오류와 같은 원인의 반복을 막는다는 설명"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림이 두 번 발송됐을 때, 잠금 키를 두는 방식으로 오류를 고치기로 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 판단했던 내용을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "잠금 키 방식을 수정 방안으로 선택한 근거를 장애 원인과 연결해 구체적으로 설명한다.",
            "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행이 알림 중복 발송으로 이어졌다는 인과관계를 설명한다.",
            "잠금 키의 동시 실행 제한이 당장의 중복 발송을 막고 동일 원인의 반복 가능성을 줄이는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "잠금 키 방식을 선택한 근거는 제시하지만 원인과의 연결이 충분히 구체적이지 않다.",
            "스케줄러 중복 실행이나 잠금의 효과를 설명하지만, 로그로 확인한 사실 또는 반복 방지 원리에 대한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키 방식을 선택한 판단 근거를 제시하지 못한다.",
            "로그에서 확인한 원인과 연결하지 않은 채 잠금을 추가했다는 조치만 설명하거나, 해당 조치가 중복 발송을 막는 이유를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업의 요청을 목적에 맞는 구현 범위로 구체화할 수 있는지 검증한다. 세탁소 인터뷰를 바탕으로 요구사항 정의서에 포함할 기능의 범위를 정한 기준 하나를 묻는다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 인터뷰를 바탕으로 요구사항 정의서를 작성한 장면이다.",
          "task": "인터뷰에서 나온 요청을 서비스 목적에 맞게 정리하고 개발 담당 팀원과 조정할 구현 범위를 구체화하는 것이다.",
          "action": "기능의 포함 여부를 판단한 기준을 밝히고, 실제 요청에 그 기준을 적용해 범위를 구분한 사례를 설명한다.",
          "result": "선택한 기준에 따라 요구사항의 포함 범위와 제외 범위가 어떻게 명확해졌는지 드러난다. 실제 구현 성과는 전제하지 않는다."
        },
        "expectedEvidence": [
          "요구사항 정의서에 포함할 기능의 범위를 정한 구체적인 판단 기준",
          "그 기준을 세탁소 인터뷰에서 확인한 요청의 목적과 연결한 설명",
          "실제 요청의 포함 여부에 기준을 적용하여 구현 범위를 명확히 한 사례"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서에 담을 기능의 범위를 정한 기준은 무엇이었나요?",
      "answerTip": "실제로 겪은 사례 하나를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "기능의 포함 범위를 정한 기준이 구체적이며 실제 범위 결정에 적용할 수 있는 수준으로 드러난다.",
            "세탁소 인터뷰에서 확인한 요청의 목적과 범위 판단 기준의 관계를 명확히 설명한다.",
            "실제 요청에 기준을 적용한 사례에서 포함하거나 제외한 경계가 개발 담당자와 논의할 수 있을 만큼 분명하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "기능의 포함 범위를 정한 기준은 제시하지만 표현이 포괄적이거나 적용 조건이 일부 불명확하다.",
            "인터뷰 요청과 기준의 연결은 드러나지만 요청의 목적에 대한 설명이 부족하다.",
            "범위를 결정한 사례는 있으나 포함 범위와 제외 범위의 경계가 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "범위 판단 기준을 제시하지 못하고 요구사항 목록이나 작성 활동만 설명한다.",
            "인터뷰에서 확인한 요청의 목적과 범위 결정의 관계가 드러나지 않는다.",
            "실제 요청에 기준을 적용한 설명이 없어 구현 범위를 구체화했는지 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 구현 가능한 화면 흐름과 상태로 구체화할 수 있는지 검증한다. 화면설계서에서 예외 상황을 화면에 표현하는 방식을 정한 기준 하나를 묻는다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 Figma로 작성한 장면이다.",
          "task": "예외 상황의 화면 동작을 개발자와 디자이너가 해석할 수 있도록 구체화하는 것이다.",
          "action": "예외 상황을 화면에 표현하는 방식을 선택한 기준을 밝히고, 실제 설계 사례에서 그 기준이 화면 상태와 후속 흐름의 표현에 어떻게 적용됐는지 설명한다.",
          "result": "선택한 표현 방식으로 예외 상황의 화면 동작이 얼마나 명확해졌는지 드러난다. 실제 구현이나 추가 질문 감소 성과는 전제하지 않는다."
        },
        "expectedEvidence": [
          "예외 상황을 화면에 표현하는 방식을 정한 구체적인 판단 기준",
          "실제 예외 상황의 발생 조건과 화면 상태 또는 후속 흐름을 연결한 설계 사례",
          "선택한 표현 방식이 화면 동작이나 안내 문구의 해석상 모호함을 줄이는 이유"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 화면설계서 28장을 작성할 때, 예외 상황을 화면에 표현하는 방식을 정한 기준은 무엇이었나요?",
      "answerTip": "기억나는 사례를 골라 본인의 생각을 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 화면 표현 방식을 정한 기준이 구체적이며 설계 선택과 직접 연결된다.",
            "실제 예외 상황의 발생 조건에 따라 화면 상태나 후속 흐름을 어떻게 표현했는지 사례로 뒷받침한다.",
            "선택한 방식이 화면 동작이나 안내 문구의 모호함을 줄여 구현 내용을 명확히 하는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황의 화면 표현 기준은 제시하지만 구체적인 설계 선택과의 연결이 일부 부족하다.",
            "예외 상황의 설계 사례는 있으나 발생 조건과 화면 상태 또는 후속 흐름의 연결이 불명확하다.",
            "표현 방식을 선택한 이유는 설명하지만 구현 내용의 모호함을 줄이는 데 어떤 도움이 되는지는 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 표현 방식을 정한 기준 없이 화면설계서의 분량이나 도구 사용만 설명한다.",
            "실제 예외 상황과 화면 동작의 연결이 드러나는 설계 사례를 제시하지 못한다.",
            "선택한 표현 방식의 이유를 설명하지 못해 구현 가능한 수준으로 구체화했는지 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방의 이상 여부를 확인하고 불확실한 투약을 중단할 수 있는지 검증한다. 평소의 두 배로 입력된 진통제 처방에서 투약을 멈추기로 한 판단의 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력되었던 경험이다.",
          "task": "해당 처방대로 투약해도 되는지 확인되지 않은 상태에서 투약 진행 여부를 판단해야 했다.",
          "action": "처방 용량의 차이를 어떤 정보와 비교했는지 설명하고, 확인되지 않은 처방으로 투약을 진행하지 않기로 한 이유를 제시한다.",
          "result": "담당의 확인으로 입력 오류가 밝혀졌다는 사실이 투약 중단 판단의 타당성을 뒷받침한다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 한 구체적인 판단 근거",
          "처방 용량의 이상을 인식하게 한 비교 정보와 확인되지 않은 사항",
          "담당의 확인으로 밝혀진 입력 오류와 중단 판단의 연결"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어왔던 경험에서, 투약을 멈추기로 판단한 근거를 말씀해 주세요.",
      "answerTip": "당시의 구체적인 경험을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
